using InventorySystem.Application.Commands; using InventorySystem.Application.Common.Exceptions; using InventorySystem.Application.DTOs; using InventorySystem.Application.Interfaces; using InventorySystem.Domain.Entities; using MediatR; namespace InventorySystem.Application.Handlers; public sealed class CreatePersonnelCommandHandler(IPersonnelRepository r):IRequestHandler<CreatePersonnelCommand,PersonnelDetailDto>{public async Task<PersonnelDetailDto> Handle(CreatePersonnelCommand x,CancellationToken ct){if(await r.SicilNoExistsAsync(x.SicilNo,null,ct))throw new ConflictException("Bu sicil numarası aktif bir personel tarafından kullanılıyor.");var p=new Personnel(x.SicilNo,x.Ad,x.Soyad,x.Departman,x.Pozisyon,x.Eposta,x.ZimmetNo,x.AktifMi);await r.AddAsync(p,ct);await r.SaveChangesAsync(ct);return p.ToDetailDto();}} public sealed class UpdatePersonnelCommandHandler(IPersonnelRepository r,IDateTimeProvider d):IRequestHandler<UpdatePersonnelCommand,PersonnelDetailDto>{public async Task<PersonnelDetailDto> Handle(UpdatePersonnelCommand x,CancellationToken ct){var p=await r.GetByIdAsync(x.Id,ct)??throw new NotFoundException("Personel kaydı bulunamadı.");if(await r.SicilNoExistsAsync(x.SicilNo,x.Id,ct))throw new ConflictException("Bu sicil numarası aktif bir personel tarafından kullanılıyor.");p.Update(x.SicilNo,x.Ad,x.Soyad,x.Departman,x.Pozisyon,x.Eposta,x.ZimmetNo,x.AktifMi,d.UtcNow);await r.SaveChangesAsync(ct);return p.ToDetailDto();}} public sealed class DeletePersonnelCommandHandler(IPersonnelRepository r,IDateTimeProvider d):IRequestHandler<DeletePersonnelCommand>{public async Task Handle(DeletePersonnelCommand x,CancellationToken ct){var p=await r.GetByIdAsync(x.Id,ct)??throw new NotFoundException("Personel kaydı bulunamadı.");p.SoftDelete(d.UtcNow);await r.SaveChangesAsync(ct);}}
